steps.command:
cat > /tmp/testboot.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 120
spawn qemu-system-x86_64 -m 1024 -cdrom /app/alpine.iso -boot d -nographic -no-reboot
expect "boot:" { send "\r" }
log_user 1
expect {
  "login:" { send "root\r"; exp_continue }
  timeout { puts "\nTIMEOUT"; exit 2 }
  eof { puts "\nEOF"; exit 3 }
}
EOF
chmod +x /tmp/testboot.exp
timeout 90 /tmp/testboot.exp 2>&1 | tail -120

python3 - <<'PY'
try:
 import pexpect; print('pexpect', pexpect.__version__)
except Exception as e: print('no pexpect',e)
PY
nc -h 2>&1 | head -20

cat > /tmp/test_ssh.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 20
log_user 1
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost
expect {
  "password:" { send "password123\r" }
  timeout { puts "\nNO_PASSWORD_PROMPT"; exit 2 }
  eof { puts "\nEOF_BEFORE_PASSWORD"; exit 3 }
}
expect {
  -re {[#\$] $} { send "echo SSH_OK_$(hostname)\r"; exp_continue }
  "SSH_OK_" { send "id\r"; exp_continue }
  "uid=0(root)" { send "exit\r"; exp_continue }
  eof { puts "\nSSH_TEST_DONE"; exit 0 }
  timeout { puts "\nNO_SHELL_PROMPT"; exit 4 }
}
EOF
chmod +x /tmp/test_ssh.exp
timeout 30 /tmp/test_ssh.exp 2>&1 | cat -v | tail -60

cat > /tmp/test_ssh.exp <<'EOF'
#!/usr/bin/expect -f
set timeout 25
log_user 1
spawn ssh -p 2222 -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null root@localhost
expect {
  "password:" { send "password123\r" }
  timeout { puts "\nNO_PASSWORD_PROMPT"; exit 2 }
  eof { puts "\nEOF_BEFORE_PASSWORD"; exit 3 }
}
expect {
  "localhost:~#" { send "echo SSH_TEST_OK; id; pwd\r" }
  timeout { puts "\nNO_SHELL_PROMPT"; exit 4 }
}
expect {
  "SSH_TEST_OK" { send "exit\r" }
  timeout { puts "\nNO_COMMAND_OUTPUT"; exit 5 }
}
expect eof
puts "\nSSH_TEST_DONE"
EOF
timeout 35 /tmp/test_ssh.exp 2>&1 | cat -v | tail -60
